SELECT DISTINCT ON ("Ord_Link") "Ord_Link", "remain_amt", "FillAmt", "RecordVault" 
FROM "orderExecutions" 
ORDER BY "Ord_Link", "RecordVault" DESC;

SELECT COUNT(*) FROM (
    SELECT e."Ord_Link"
    FROM "orderExecutions" e
    GROUP BY e."Ord_Link"
) t;

SELECT DISTINCT ON ("Ord_Link") "Ord_Link", "remain_amt", "expireSpot"
FROM "orderExecutions"
ORDER BY "Ord_Link", "expireSpot" DESC;

SELECT DISTINCT ON ("Ord_Link") "Ord_Link", "FillAmt", "FILL_SUM", "remain_amt"
FROM "orderExecutions"
ORDER BY "Ord_Link", "RecordVault" DESC;

SELECT COUNT(*) FROM (
    SELECT e."Ord_Link"
    FROM "orderExecutions" e
    WHERE e."ExecMARK" IN (
        SELECT MAX(e2."ExecMARK")
        FROM "orderExecutions" e2
        GROUP BY e2."Ord_Link"
    )
) t;

SELECT COUNT(*) FROM (
    SELECT e."Ord_Link"
    FROM "orderExecutions" e
    WHERE e."RecordVault" IN (
        SELECT MAX(e2."RecordVault")
        FROM "orderExecutions" e2
        GROUP BY e2."Ord_Link"
    )
) t;

SELECT DISTINCT ON ("Ord_Link") "Ord_Link", "FILL_SUM"
FROM "orderExecutions"
ORDER BY "Ord_Link", "RecordVault" DESC;
